     let items2 = extract_from_envelope(&env2, "2026-07-14T01:00:00Z");
     let items3 = extract_from_envelope(&env3, "2026-07-14T02:00:00Z");

     write_items(&dir, &items1);
     write_items(&dir, &items2);
     write_items(&dir, &items3);

