     let entity_b_item = loaded
         .iter()
         .find(|i| i.attribution.entity_id == "entity_b")
         .expect("entity_b item exists");
     assert_eq!(
         entity_b_item.provenance.run_ids,
         vec!["run_003".to_string()]
     );
 }

