     assert_eq!(case["state"], "terminated");
     assert_eq!(case["close_reason"], "rejected");
     assert_eq!(case["case_id"], envelope["case_ref"]);
     assert_eq!(case["plan_ref"], envelope["plan_ref"]);
     assert_eq!(case["run_ids"], serde_json::json!([run_id]));
