         .join("cases")
         .join(format!("{}.json", envelope["case_ref"].as_str().unwrap()));
     let case: serde_json::Value = serde_json::from_slice(&fs::read(case_file).unwrap()).unwrap();
     assert_eq!(case["state"], "terminated");
     assert_eq!(case["close_reason"], "escalated");
