         .unwrap();
     assert_eq!(rejected.status.code(), Some(0));
     assert_eq!(
         String::from_utf8(rejected.stdout).unwrap().lines().count(),
         1
     );
     let newest = Command::new(env!("CARGO_BIN_EXE_sea-forge"))
         .args([
             "recall",
             "generate",
             "--root",
             root.to_str().unwrap(),
             "--limit",
