#[test]
fn memory_scope_grant_carries_boundary() {
    let bundle = recall_bundle("entity:entity_a");
    let action = recall_action("entity_a", "entity_a");
    let decision = evaluate_recall(bundle, &action);
    assert_eq!(decision.verdict, sea_forge_core::types::Verdict::Allow);

    let root = tempfile::tempdir().unwrap();
    let stream =
        sea_forge_ledger::LedgerStream::open(root.path(), "recall-authority", "test").unwrap();
    let committed = stream
        .commit_typed("authority_decision", vec![], &decision, vec![])
        .unwrap();

    let bundle2 = recall_bundle("entity:entity_a");
    let engine = PolicyAuthorityEngine::new(bundle2).unwrap();
    // Re-evaluate to get a fresh issued decision for the grant.
    let binding = bundle2.resolve_identity("operator_local", ActorRole::Operator);
    // ponytail: re-issue by evaluating through the same engine that grants.
    let actor = Actor {
        actor_id: "operator_local".into(),
        role: ActorRole::Operator,
    };
    let fresh = engine
        .evaluate(AuthorityEvaluation {
            actor: &actor,
            binding,
            run_id: "run_recall",
            case_id: "case_recall",
            plan_item_id: "item_recall",
            sequence: 2,
            action: &action,
            workspace_root: Path::new("/tmp/workspace"),
            evidence_refs: vec!["intent:recall".into()],
            artifacts_root: None,
            timeout_secs: None,
            env_keys: Default::default(),
            domainforge_candidate: None,
            environment: None,
        })
        .unwrap();
    let committed2 = stream
        .commit_typed("authority_decision", vec![], &fresh, vec![])
        .unwrap();
    let grant = engine.grant(&fresh, &committed2, &action, None).unwrap();
    assert_eq!(
        grant.memory_scope(),
        Some("entity:entity_a"),
        "grant must carry the matched memory_scope boundary"
    );
}

