    file.write_all(contents.as_bytes())
        .expect("unable to write file");
}

fn create_registry(dir: &Path) -> std::path::PathBuf {
    let registry_path = dir.join(".sea-registry.toml");
    let registry = r#"
version = 1
default_namespace = "default"

[[namespaces]]
namespace = "acme.order"
patterns = ["order.sea"]

